const contexts = new WeakMap();
export function getContext(result) {
	if (contexts.has(result)) {
		return contexts.get(result);
	}
	let ctx = {
		c: 0,
		islandCount: 0,
		get id() {
			return "p" + this.c.toString();
		},
		signals: new Map(),
		propsToSignals: new Map()
	};
	contexts.set(result, ctx);
	return ctx;
}
export function incrementId(ctx) {
	let id = ctx.id;
	ctx.c++;
	return id;
}
export function incrementIslandId(ctx) {
	const islandId = ctx.islandCount;
	ctx.islandCount++;
	return islandId;
}
